BEGIN IMMEDIATE;
UPDATE sd_tx_copy SET available = 0
WHERE id = 203 AND available = 1;
INSERT INTO sd_tx_loan(copy_id, borrower)
SELECT 203, 'Learner A' WHERE changes() = 1;
COMMIT;

BEGIN IMMEDIATE;
UPDATE sd_tx_copy SET available = 0
